147	{
148	  int newEvents = 0;
149	  if (EventPoll::EVENT_READ & events) {
150	    newEvents |= EPOLLIN;
151	  }
152	  if (EventPoll::EVENT_WRITE & events) {
153	    newEvents |= EPOLLOUT;
154	  }
155	  if (EventPoll::EVENT_ERROR & events) {
156	    newEvents |= EPOLLERR;
157	  }
158	  if (EventPoll::EVENT_HUP & events) {
159	    newEvents |= EPOLLHUP;
160	  }
161	  return newEvents;
162	}
