245	    socketEntries_.erase(i);
246	  }
247	  else {
248	    // If socket is closed, then it seems it is automatically removed from
249	    // epoll, so following EPOLL_CTL_MOD may fail.
250	    struct epoll_event epEvent = socketEntry.getEvents();
251	    r = epoll_ctl(epfd_, EPOLL_CTL_MOD, socketEntry.getSocket(), &epEvent);
252	    errNum = errno;
253	    if (r == -1) {
254	      A2_LOG_DEBUG(fmt("Failed to delete socket event, but may be ignored:%s",
