51	EpollEventPoll::KSocketEntry::KSocketEntry(sock_t s)
52	    : SocketEntry<KCommandEvent, KADNSEvent>(s)
53	{
54	}
55	
56	int accumulateEvent(int events, const EpollEventPoll::KEvent& event)
57	{
58	  return events | event.getEvents();
59	}
60	
61	struct epoll_event EpollEventPoll::KSocketEntry::getEvents()
62	{
63	  struct epoll_event epEvent;
64	  memset(&epEvent, 0, sizeof(struct epoll_event));
65	  epEvent.data.ptr = this;
66	
67	#ifdef ENABLE_ASYNC_DNS
68	
69	  epEvent.events =
70	      std::accumulate(adnsEvents_.begin(), adnsEvents_.end(),
71	                      std::accumulate(commandEvents_.begin(),
72	                                      commandEvents_.end(), 0, accumulateEvent),
73	                      accumulateEvent);
74	
75	#else // !ENABLE_ASYNC_DNS
76	
77	  epEvent.events = std::accumulate(commandEvents_.begin(), commandEvents_.end(),
78	                                   0, accumulateEvent);
79	
80	#endif // !ENABLE_ASYNC_DNS
81	  return epEvent;
82	}
83	
84	EpollEventPoll::EpollEventPoll()
85	    : epEventsSize_(EPOLL_EVENTS_MAX),
86	      epEvents_(make_unique<struct epoll_event[]>(epEventsSize_))
87	{
88	  epfd_ = epoll_create(EPOLL_EVENTS_MAX);
89	}
90	
91	EpollEventPoll::~EpollEventPoll()
92	{
93	  if (epfd_ != -1) {
94	    int r = close(epfd_);
95	    int errNum = errno;
96	    if (r == -1) {
97	      A2_LOG_ERROR(fmt("Error occurred while closing epoll file descriptor"
98	                       " %d: %s",
99	                       epfd_, util::safeStrerror(errNum).c_str()));
100	    }
101	  }
102	}
103	
104	bool EpollEventPoll::good() const { return epfd_ != -1; }
105	
106	void EpollEventPoll::poll(const struct timeval& tv)
107	{
108	  // timeout is millisec
109	  int timeout = tv.tv_sec * 1000 + tv.tv_usec / 1000;
110	
111	  int res;
112	  while ((res = epoll_wait(epfd_, epEvents_.get(), EPOLL_EVENTS_MAX,
113	                           timeout)) == -1 &&
114	         errno == EINTR)
115	    ;
116	
117	  if (res > 0) {
118	    for (int i = 0; i < res; ++i) {
119	      KSocketEntry* p = reinterpret_cast<KSocketEntry*>(epEvents_[i].data.ptr);
120	      p->processEvents(epEvents_[i].events);
121	    }
122	  }
123	  else if (res == -1) {
124	    int errNum = errno;
125	    A2_LOG_INFO(
126	        fmt("epoll_wait error: %s", util::safeStrerror(errNum).c_str()));
127	  }
128	#ifdef ENABLE_ASYNC_DNS
129	  // It turns out that we have to call ares_process_fd before ares's
130	  // own timeout and ares may create new sockets or closes socket in
131	  // their API. So we call ares_process_fd for all ares_channel and
132	  // re-register their sockets.
133	  for (auto& i : nameResolverEntries_) {
134	    auto& ent = i.second;
135	    ent.processTimeout();
136	    ent.removeSocketEvents(this);
137	    ent.addSocketEvents(this);
138	  }
139	#endif // ENABLE_ASYNC_DNS
140	
141	  // TODO timeout of name resolver is determined in Command(AbstractCommand,
142	  // DHTEntryPoint...Command)
143	}
144	
145	namespace {
146	int translateEvents(EventPoll::EventType events)
147	{
148	  int newEvents = 0;
149	  if (EventPoll::EVENT_READ & events) {
150	    newEvents |= EPOLLIN;
151	  }
152	  if (EventPoll::EVENT_WRITE & events) {
153	    newEvents |= EPOLLOUT;
154	  }
155	  if (EventPoll::EVENT_ERROR & events) {
156	    newEvents |= EPOLLERR;
157	  }
158	  if (EventPoll::EVENT_HUP & events) {
159	    newEvents |= EPOLLHUP;
160	  }
161	  return newEvents;
162	}
163	} // namespace
164	
165	bool EpollEventPoll::addEvents(sock_t socket,
166	                               const EpollEventPoll::KEvent& event)
167	{
168	  auto i = socketEntries_.lower_bound(socket);
169	  int r = 0;
170	  int errNum = 0;
171	  if (i != std::end(socketEntries_) && (*i).first == socket) {
172	    auto& socketEntry = (*i).second;
173	
174	    event.addSelf(&socketEntry);
175	
176	    struct epoll_event epEvent = socketEntry.getEvents();
177	    r = epoll_ctl(epfd_, EPOLL_CTL_MOD, socketEntry.getSocket(), &epEvent);
178	    if (r == -1) {
179	      // try EPOLL_CTL_ADD: There is a chance that previously socket X is
180	      // added to epoll, but it is closed and is not yet removed from
181	      // SocketEntries. In this case, EPOLL_CTL_MOD is failed with ENOENT.
182	
183	      r = epoll_ctl(epfd_, EPOLL_CTL_ADD, socketEntry.getSocket(), &epEvent);
184	      errNum = errno;
185	    }
186	  }
187	  else {
188	    i = socketEntries_.insert(i, std::make_pair(socket, KSocketEntry(socket)));
189	    auto& socketEntry = (*i).second;
190	    if (socketEntries_.size() > epEventsSize_) {
191	      epEventsSize_ *= 2;
192	      epEvents_ = make_unique<struct epoll_event[]>(epEventsSize_);
193	    }
194	
195	    event.addSelf(&socketEntry);
196	
197	    struct epoll_event epEvent = socketEntry.getEvents();
198	    r = epoll_ctl(epfd_, EPOLL_CTL_ADD, socketEntry.getSocket(), &epEvent);
199	    errNum = errno;
200	  }
201	  if (r == -1) {
202	    A2_LOG_DEBUG(fmt("Failed to add socket event %d:%s", socket,
203	                     util::safeStrerror(errNum).c_str()));
204	    return false;
205	  }
206	  else {
207	    return true;
208	  }
209	}
210	
211	bool EpollEventPoll::addEvents(sock_t socket, Command* command,
212	                               EventPoll::EventType events)
213	{
214	  int epEvents = translateEvents(events);
215	  return addEvents(socket, KCommandEvent(command, epEvents));
216	}
217	
218	#ifdef ENABLE_ASYNC_DNS
219	bool EpollEventPoll::addEvents(sock_t socket, Command* command, int events,
220	                               const std::shared_ptr<AsyncNameResolver>& rs)
221	{
222	  return addEvents(socket, KADNSEvent(rs, command, socket, events));
223	}
224	#endif // ENABLE_ASYNC_DNS
225	
226	bool EpollEventPoll::deleteEvents(sock_t socket,
227	                                  const EpollEventPoll::KEvent& event)
228	{
229	  auto i = socketEntries_.find(socket);
230	  if (i == std::end(socketEntries_)) {
231	    A2_LOG_DEBUG(fmt("Socket %d is not found in SocketEntries.", socket));
232	    return false;
233	  }
234	
235	  auto& socketEntry = (*i).second;
236	  event.removeSelf(&socketEntry);
237	  int r = 0;
238	  int errNum = 0;
239	  if (socketEntry.eventEmpty()) {
240	    // In kernel before 2.6.9, epoll_ctl with EPOLL_CTL_DEL requires non-null
241	    // pointer of epoll_event.
242	    struct epoll_event ev = {0, {0}};
243	    r = epoll_ctl(epfd_, EPOLL_CTL_DEL, socketEntry.getSocket(), &ev);
244	    errNum = errno;
245	    socketEntries_.erase(i);
246	  }
247	  else {
248	    // If socket is closed, then it seems it is automatically removed from
249	    // epoll, so following EPOLL_CTL_MOD may fail.
250	    struct epoll_event epEvent = socketEntry.getEvents();
251	    r = epoll_ctl(epfd_, EPOLL_CTL_MOD, socketEntry.getSocket(), &epEvent);
252	    errNum = errno;
253	    if (r == -1) {
254	      A2_LOG_DEBUG(fmt("Failed to delete socket event, but may be ignored:%s",
255	                       util::safeStrerror(errNum).c_str()));
256	    }
257	  }
258	  if (r == -1) {
259	    A2_LOG_DEBUG(fmt("Failed to delete socket event:%s",
260	                     util::safeStrerror(errNum).c_str()));
261	    return false;
262	  }
263	  else {
264	    return true;
265	  }
266	}
267	
268	#ifdef ENABLE_ASYNC_DNS
269	bool EpollEventPoll::deleteEvents(sock_t socket, Command* command,
270	                                  const std::shared_ptr<AsyncNameResolver>& rs)
271	{
272	  return deleteEvents(socket, KADNSEvent(rs, command, socket, 0));
273	}
274	#endif // ENABLE_ASYNC_DNS
275	
276	bool EpollEventPoll::deleteEvents(sock_t socket, Command* command,
277	                                  EventPoll::EventType events)
278	{
279	  int epEvents = translateEvents(events);
280	  return deleteEvents(socket, KCommandEvent(command, epEvents));
281	}
282	
283	#ifdef ENABLE_ASYNC_DNS
284	bool EpollEventPoll::addNameResolver(
285	    const std::shared_ptr<AsyncNameResolver>& resolver, Command* command)
286	{
287	  auto key = std::make_pair(resolver.get(), command);
288	  auto itr = nameResolverEntries_.lower_bound(key);
289	
290	  if (itr != std::end(nameResolverEntries_) && (*itr).first == key) {
291	    return false;
292	  }
293	
294	  itr = nameResolverEntries_.insert(
295	      itr, std::make_pair(key, KAsyncNameResolverEntry(resolver, command)));
296	  (*itr).second.addSocketEvents(this);
297	  return true;
298	}
299	
300	bool EpollEventPoll::deleteNameResolver(
301	    const std::shared_ptr<AsyncNameResolver>& resolver, Command* command)
302	{
303	  auto key = std::make_pair(resolver.get(), command);
304	  auto itr = nameResolverEntries_.find(key);
305	  if (itr == std::end(nameResolverEntries_)) {
306	    return false;
307	  }
308	
309	  (*itr).second.removeSocketEvents(this);
310	  nameResolverEntries_.erase(itr);
311	  return true;
312	}
313	#endif // ENABLE_ASYNC_DNS
314	
315	} // namespace aria2
