57	
58	void SelectEventPoll::CommandEvent::processEvents(int events)
59	{
60	  if ((events_ & events) ||
61	      ((EventPoll::EVENT_ERROR | EventPoll::EVENT_HUP) & events)) {
62	    command_->setStatusActive();
63	  }
64	  if (EventPoll::EVENT_READ & events) {
65	    command_->readEventReceived();
66	  }
67	  if (EventPoll::EVENT_WRITE & events) {
68	    command_->writeEventReceived();
69	  }
70	  if (EventPoll::EVENT_ERROR & events) {
71	    command_->errorEventReceived();
72	  }
73	  if (EventPoll::EVENT_HUP & events) {
74	    command_->hupEventReceived();
75	  }
76	}
