78	SelectEventPoll::SocketEntry::SocketEntry(sock_t socket) : socket_(socket) {}
79	
80	void SelectEventPoll::SocketEntry::addCommandEvent(Command* command, int events)
81	{
82	  CommandEvent cev(command, events);
83	  auto i = std::find(commandEvents_.begin(), commandEvents_.end(), cev);
84	  if (i == commandEvents_.end()) {
85	    commandEvents_.push_back(cev);
86	  }
87	  else {
88	    (*i).addEvents(events);
89	  }
90	}
91	void SelectEventPoll::SocketEntry::removeCommandEvent(Command* command,
92	                                                      int events)
93	{
94	  CommandEvent cev(command, events);
95	  auto i = std::find(commandEvents_.begin(), commandEvents_.end(), cev);
96	  if (i == commandEvents_.end()) {
97	    // not found
98	  }
99	  else {
100	    (*i).removeEvents(events);
101	    if ((*i).eventsEmpty()) {
102	      commandEvents_.erase(i);
103	    }
104	  }
105	}
106	void SelectEventPoll::SocketEntry::processEvents(int events)
107	{
108	  using namespace std::placeholders;
109	  std::for_each(commandEvents_.begin(), commandEvents_.end(),
110	                std::bind(&CommandEvent::processEvents, _1, events));
111	}
112	
113	int accumulateEvent(int events, const SelectEventPoll::CommandEvent& event)
114	{
115	  return events | event.getEvents();
