169	
170	void SelectEventPoll::poll(const struct timeval& tv)
171	{
172	  fd_set rfds;
173	  fd_set wfds;
174	
175	  memcpy(&rfds, &rfdset_, sizeof(fd_set));
176	  memcpy(&wfds, &wfdset_, sizeof(fd_set));
177	
178	#ifdef __MINGW32__
179	  fd_set efds;
180	  memcpy(&efds, &wfdset_, sizeof(fd_set));
181	#endif // __MINGW32__
182	
183	#ifdef ENABLE_ASYNC_DNS
184	
185	  for (auto& i : nameResolverEntries_) {
186	    auto& entry = i.second;
187	    auto fd = entry.getFds(&rfds, &wfds);
188	    // TODO force error if fd == 0
189	    if (fdmax_ < fd) {
190	      fdmax_ = fd;
191	    }
192	  }
193	
194	#endif // ENABLE_ASYNC_DNS
195	  int retval;
196	  do {
197	    struct timeval ttv = tv;
198	#ifdef __MINGW32__
199	    // winsock will report non-blocking connect() errors in efds,
200	    // unlike posix, which will mark such sockets as writable.
201	    retval = select(fdmax_ + 1, &rfds, &wfds, &efds, &ttv);
202	#else  // !__MINGW32__
203	    retval = select(fdmax_ + 1, &rfds, &wfds, nullptr, &ttv);
204	#endif // !__MINGW32__
205	  } while (retval == -1 && errno == EINTR);
206	  if (retval > 0) {
207	    for (auto& i : socketEntries_) {
208	      auto& e = i.second;
209	      int events = 0;
210	      if (FD_ISSET(e.getSocket(), &rfds)) {
211	        events |= EventPoll::EVENT_READ;
212	      }
213	      if (FD_ISSET(e.getSocket(), &wfds)) {
214	        events |= EventPoll::EVENT_WRITE;
215	      }
216	#ifdef __MINGW32__
217	      if (FD_ISSET(e.getSocket(), &efds)) {
218	        events |= EventPoll::EVENT_ERROR;
219	      }
220	#endif // __MINGW32__
221	      e.processEvents(events);
222	    }
223	  }
224	  else if (retval == -1) {
