262	  for (auto& i : socketEntries_) {
263	    auto& e = i.second;
264	    sock_t fd = e.getSocket();
265	#ifndef __MINGW32__
266	    if (fd < 0 || FD_SETSIZE <= fd) {
267	      A2_LOG_WARN("Detected file descriptor >= FD_SETSIZE or < 0. "
268	                  "Download may slow down or fail.");
269	      continue;
270	    }
271	#endif // !__MINGW32__
272	    int events = e.getEvents();
273	    if (events & EventPoll::EVENT_READ) {
274	#ifdef __MINGW32__
275	      checkFdCountMingw(rfdset_);
276	#endif // __MINGW32__
277	      FD_SET(fd, &rfdset_);
278	    }
279	    if (events & EventPoll::EVENT_WRITE) {
280	#ifdef __MINGW32__
281	      checkFdCountMingw(wfdset_);
282	#endif // __MINGW32__
283	      FD_SET(fd, &wfdset_);
284	    }
285	    if (fdmax_ < fd) {
286	      fdmax_ = fd;
287	    }
288	  }
289	}
290	
291	bool SelectEventPoll::addEvents(sock_t socket, Command* command,
292	                                EventPoll::EventType events)
293	{
294	  auto i = socketEntries_.lower_bound(socket);
295	  if (i != std::end(socketEntries_) && (*i).first == socket) {
296	    (*i).second.addCommandEvent(command, events);
297	  }
298	  else {
299	    i = socketEntries_.insert(i, std::make_pair(socket, SocketEntry(socket)));
300	    (*i).second.addCommandEvent(command, events);
301	  }
302	  updateFdSet();
303	  return true;
304	}
305	
306	bool SelectEventPoll::deleteEvents(sock_t socket, Command* command,
307	                                   EventPoll::EventType events)
308	{
309	  auto i = socketEntries_.find(socket);
310	  if (i == std::end(socketEntries_)) {
311	    A2_LOG_DEBUG(fmt("Socket %d is not found in SocketEntries.", socket));
312	    return false;
313	  }
314	
315	  auto& socketEntry = (*i).second;
316	  socketEntry.removeCommandEvent(command, events);
317	  if (socketEntry.eventEmpty()) {
318	    socketEntries_.erase(i);
319	  }
320	  updateFdSet();
321	  return true;
322	}
323	
324	#ifdef ENABLE_ASYNC_DNS
325	bool SelectEventPoll::addNameResolver(
326	    const std::shared_ptr<AsyncNameResolver>& resolver, Command* command)
327	{
328	  auto key = std::make_pair(resolver.get(), command);
329	  auto itr = nameResolverEntries_.lower_bound(key);
330	  if (itr != std::end(nameResolverEntries_) && (*itr).first == key) {
331	    return false;
332	  }
333	
334	  nameResolverEntries_.insert(
335	      itr, std::make_pair(key, AsyncNameResolverEntry(resolver, command)));
336	
337	  return true;
338	}
339	
340	bool SelectEventPoll::deleteNameResolver(
341	    const std::shared_ptr<AsyncNameResolver>& resolver, Command* command)
342	{
343	  auto key = std::make_pair(resolver.get(), command);
344	  return nameResolverEntries_.erase(key) == 1;
345	}
346	#endif // ENABLE_ASYNC_DNS
347	
