170	                                const KqueueEventPoll::KEvent& event)
171	{
172	  auto i = socketEntries_.lower_bound(socket);
173	  int r = 0;
174	  struct timespec zeroTimeout = {0, 0};
175	  struct kevent changelist[2];
176	  size_t n;
177	  if (i != std::end(socketEntries_) && (*i).first == socket) {
178	    auto& socketEntry = (*i).second;
179	    event.addSelf(&socketEntry);
180	    n = socketEntry.getEvents(changelist);
181	  }
182	  else {
183	    i = socketEntries_.insert(i, std::make_pair(socket, KSocketEntry(socket)));
184	    auto& socketEntry = (*i).second;
185	    if (socketEntries_.size() > kqEventsSize_) {
186	      kqEventsSize_ *= 2;
187	      kqEvents_ = make_unique<struct kevent[]>(kqEventsSize_);
188	    }
189	    event.addSelf(&socketEntry);
190	    n = socketEntry.getEvents(changelist);
191	  }
192	  r = kevent(kqfd_, changelist, n, changelist, 0, &zeroTimeout);
193	  int errNum = errno;
194	  if (r == -1) {
195	    A2_LOG_DEBUG(fmt("Failed to add socket event %d:%s", socket,
196	                     util::safeStrerror(errNum).c_str()));
197	    return false;
198	  }
199	  else {
200	    return true;
201	  }
